const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
// 1. Geometry & Time Definitions
var shanghai = ee.Geometry.Point([121.4737, 31.2304]).buffer(50000); // 50km buffer
var beijing = ee.Geometry.Point([116.4074, 39.9042]).buffer(50000); // 50km buffer

var baselineStart = '2000-08-05';
var baselineEnd = '2012-08-13'; // 12 years + 1 week
var targetStart = '2013-08-05';
var targetEnd = '2013-08-13'; // 8-day period

// 2. Data Acquisition - MODIS LST Terra 8-day
var lstCol = ee.ImageCollection('MODIS/061/MOD11A2')
  .select('LST_Day_1km');

// Function to process LST
function processLST(col, geometry) {
  return col.mean()
    .multiply(0.02) // scale factor
    .subtract(273.15) // K to C
    .reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: geometry,
      scale: 1000,
      maxPixels: 1e9
    }).get('LST_Day_1km');
}

// Baseline period (2000-2012 same week)
var baselineShanghai = lstCol.filterDate(baselineStart, baselineEnd).filterBounds(shanghai);
var baselineBeijing = lstCol.filterDate(baselineStart, baselineEnd).filterBounds(beijing);

// Target period (2013)
var targetShanghai = lstCol.filterDate(targetStart, targetEnd).filterBounds(shanghai);
var targetBeijing = lstCol.filterDate(targetStart, targetEnd).filterBounds(beijing);

// Check data availability
var baseShCount = baselineShanghai.size().getInfo();
var baseBjCount = baselineBeijing.size().getInfo();
var targetShCount = targetShanghai.size().getInfo();
var targetBjCount = targetBeijing.size().getInfo();

print(`Shanghai baseline images: ${baseShCount}`);
print(`Beijing baseline images: ${baseBjCount}`);
print(`Shanghai target images: ${targetShCount}`);
print(`Beijing target images: ${targetBjCount}`);

// Handle empty collections
if (baseShCount === 0 || baseBjCount === 0 || targetShCount === 0 || targetBjCount === 0) {
  print("<answer>C1</answer>");
  return;
}

// Calculate means
var baseShMean = baselineShanghai.mean().multiply(0.02).subtract(273.15)
  .reduceRegion({reducer: ee.Reducer.mean(), geometry: shanghai, scale: 1000, maxPixels: 1e9})
  .get('LST_Day_1km').getInfo();

var baseBjMean = baselineBeijing.mean().multiply(0.02).subtract(273.15)
  .reduceRegion({reducer: ee.Reducer.mean(), geometry: beijing, scale: 1000, maxPixels: 1e9})
  .get('LST_Day_1km').getInfo();

var targetShMean = targetShanghai.mean().multiply(0.02).subtract(273.15)
  .reduceRegion({reducer: ee.Reducer.mean(), geometry: shanghai, scale: 1000, maxPixels: 1e9})
  .get('LST_Day_1km').getInfo();

var targetBjMean = targetBeijing.mean().multiply(0.02).subtract(273.15)
  .reduceRegion({reducer: ee.Reducer.mean(), geometry: beijing, scale: 1000, maxPixels: 1e9})
  .get('LST_Day_1km').getInfo();

// Check for null results
if (baseShMean === null || baseBjMean === null || targetShMean === null || targetBjMean === null) {
  print("<answer>C2</answer>");
  return;
}

// Calculate anomalies
var shAnomaly = targetShMean - baseShMean;
var bjAnomaly = targetBjMean - baseBjMean;

print(`Shanghai Baseline: ${baseShMean.toFixed(2)}°C, Target: ${targetShMean.toFixed(2)}°C, Anomaly: ${shAnomaly.toFixed(2)}°C`);
print(`Beijing Baseline: ${baseBjMean.toFixed(2)}°C, Target: ${targetBjMean.toFixed(2)}°C, Anomaly: ${bjAnomaly.toFixed(2)}°C`);

// Validate temperature range (sanity check for C3)
if (Math.abs(baseShMean) > 100 || Math.abs(baseBjMean) > 100 || 
    Math.abs(targetShMean) > 100 || Math.abs(targetBjMean) > 100) {
  print("<answer>C3</answer>");
  return;
}

// Compare anomalies
if (shAnomaly > bjAnomaly) {
  print("<answer>A</answer>");
} else {
  print("<answer>B</answer>");
}
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
